describe('API Response Handling for 401 Errors', () => {
    beforeEach(() => {
        cy.visit('/protected-route'); // Visit a route that requires authentication
    });

    it('should redirect to login on 401 error', () => {
        // Mocking a 401 error response
        cy.intercept('GET', '/api/protected-resource', {
            statusCode: 401,
            body: { message: 'Unauthorized' }
        }).as('getProtectedResource');

        cy.wait('@getProtectedResource');

        // Assert that the user is redirected to the login page
        cy.url().should('include', '/login');
        cy.get('h1').should('contain', 'Login'); // Assuming there's a heading on the login page
    });

    it('should not redirect if the response is successful', () => {
        // Mocking a successful response
        cy.intercept('GET', '/api/protected-resource', {
            statusCode: 200,
            body: { data: 'Protected data' }
        }).as('getProtectedResource');

        cy.wait('@getProtectedResource');

        // Assert that the user remains on the protected route
        cy.url().should('include', '/protected-route');
        cy.get('.data-display').should('contain', 'Protected data'); // Assuming there's an element displaying the data
    });
});
